-- Phase 1 of the א'-17 rebuild: altitude/name corrections + net-new zones with
-- verified geometry, sourced directly from the official chapter א'-17 prose (pages 52-62)
-- and its coordinate appendices ב'/ג' (pages 64-80) of "פמ"ת פנים ארצי", edition 1/26 —
-- NOT the ICD-derived KML used by earlier imports. Existing zones' polygon geometry is
-- intentionally left untouched here; that is phase 2, per explicit sequencing.

-- LLP18 "יריחו": appendix + prose both confirm GND-4,000ft for general/drone traffic
-- (6,000ft applies only to scheduled air carriers). DB previously had 600ft — understated the
-- restriction. Also note the prose's UAS/light-aircraft carve-out for military-coordinated flights.
update aip_reference_zones
set max_altitude_ft = 4000,
    altitude_text = 'GND – 4,000 ft AMSL (לכלי טיס כלליים; למובילים אוויריים 6,000 ft; כטב"מ/טיסן המתואמים מול הגורם הצבאי אינם כפופים לאיסור, ראו פרק א''-11)'
where code = 'LLP18';

-- LLD42 "הטסת רחפנים ים המלח": DB had no altitude recorded at all (null/null). Official
-- appendix ב' gives GND up to -530ft (below sea level, consistent with the Dead Sea basin).
update aip_reference_zones
set min_altitude_ft = 0,
    max_altitude_ft = -530,
    altitude_text = 'GND – (-530) ft AMSL (מתחת לפני הים)'
where code = 'LLD42';

-- LLP171 / LLP173: the "יהודה ושומרון" prohibited area is published in THREE segments
-- (north/center/south). Only the center segment (LLP172) was previously imported. Adding the
-- other two with real appendix-ב' polygon geometry (not a placeholder).
insert into aip_reference_zones (name, code, kind, altitude_text, min_altitude_ft, max_altitude_ft, geom_geojson, source_sheet, source_edition) values
  ('יהודה ושומרון (מקטע צפוני)', 'LLP171', 'PROHIBITED', 'GND – 6,000 ft AMSL', 0, 6000, '{"type":"Polygon","coordinates":[[[35.447372,32.229633],[35.381228,32.065856],[35.167339,32.157264],[34.999306,32.232264],[35.036947,32.253558],[34.992644,32.292181],[34.998825,32.338572],[35.031928,32.368639],[35.027797,32.395061],[35.052997,32.452878],[35.141347,32.487714],[35.139728,32.512503],[35.188564,32.553681],[35.233028,32.567864],[35.269011,32.530447],[35.358056,32.536625],[35.410786,32.517675],[35.437992,32.464894],[35.447372,32.229633]]]}'::jsonb, 'aip_pmat_a17_1_26', '2026-08-06'),
  ('יהודה ושומרון (מקטע דרומי)', 'LLP173', 'PROHIBITED', 'GND – 6,000 ft AMSL', 0, 6000, '{"type":"Polygon","coordinates":[[[35.169258,31.740083],[35.252283,31.742278],[35.257017,31.745175],[35.323336,31.732167],[35.327356,31.71905],[35.297633,31.650158],[35.195411,31.568769],[35.207078,31.517933],[35.194303,31.421267],[35.069856,31.345431],[34.969019,31.367097],[34.907908,31.341542],[34.884017,31.355431],[34.874667,31.425172],[34.920681,31.494528],[35.169258,31.740083]]]}'::jsonb, 'aip_pmat_a17_1_26', '2026-08-06');

-- LLU (drone-specific "אסור לטיסה") zones: every existing row has max_altitude_ft = null,
-- i.e. treated as unbounded. Chapter א'-17 section 1א states a default ceiling of 1,000ft AGL for
-- all LLU zones unless stated otherwise, with two documented exceptions: LLU21 "גלילות" is capped
-- at 3,000ft AMSL, and LLU59-LLU72 are capped at 300ft AGL. This was a real functional gap — the
-- altitude-ceiling logic (src/lib/geo/flight-rules.ts) had no ceiling to enforce for any LLU zone.
update aip_reference_zones
set max_altitude_ft = 1000
where code like 'LLU%' and code <> 'LLU21';

update aip_reference_zones
set max_altitude_ft = 3000,
    altitude_text = 'GND – 3,000 ft AMSL'
where code = 'LLU21';

-- 19 LLU zones present in the official appendix ג' (LLU55-LLU73) that were never imported
-- (the earlier KML-based import only covered LLU01-LLU54). Radius/coordinates from appendix ג';
-- ceiling per the section 1א default (1,000ft AGL) or the LLU59-LLU72 override (300ft AGL).
insert into aip_reference_zones (name, code, kind, altitude_text, min_altitude_ft, max_altitude_ft, geom_geojson, source_sheet, source_edition) values
